514	import type { AppRouter } from '@repo/api';
515	import { TRPCClientError, type TRPCLink } from '@trpc/client';
516	import { observable } from '@trpc/server/observable';
517	import type { RouterInputs, RouterOutputs } from './trpc';
518	
519	type ProcedurePath = {
520	  [Router in keyof RouterInputs & string]: `${Router}.${keyof RouterInputs[Router] & string}`;
521	}[keyof RouterInputs & string];
522	
523	type Lookup<Tree, Path> = Path extends `${infer Router}.${infer Procedure}`
524	  ? Router extends keyof Tree
525	    ? Procedure extends keyof Tree[Router]
526	      ? Tree[Router][Procedure]
527	      : never
528	    : never
529	  : never;
530	
531	/** A fake answer per procedure path, such as `'greeting.greet'`, typed by the router. */
532	export type TestApiHandlers = {
533	  readonly [Path in ProcedurePath]?: (
534	    input: Lookup<RouterInputs, Path>,
535	  ) => Lookup<RouterOutputs, Path> | Promise<Lookup<RouterOutputs, Path>>;
536	};
537	
538	/** A tRPC link that answers each call from `handlers` instead of the network. */
539	export function handlerLink(handlers: TestApiHandlers): TRPCLink<AppRouter> {
540	  return () =>
541	    ({ op }) =>
542	      observable((observer) => {
543	        const handler = handlers[op.path as ProcedurePath] as
544	          | ((input: unknown) => unknown)
545	          | undefined;
546	        Promise.resolve(op.input)
547	          .then((input) => {
548	            if (!handler) {
549	              throw new Error(`TestApiProvider has no handler for ${op.path}`);
550	            }
551	            return handler(input);
552	          })
553	          .then(
554	            (data) => {
555	              observer.next({ result: { type: 'data', data } });
556	              observer.complete();
557	            },
558	            (cause: Error) => observer.error(TRPCClientError.from(cause)),
559	          );
560	      });
561	}
