import { randomUUID } from 'node:crypto';
import AxeBuilder from '@axe-core/playwright';
import { expect, type Locator, type Page, test } from '@playwright/test';

/**
 * The fixed Todo acceptance spec (ADR 0034). Playwright runs it as the
 * `<id>-acceptance` project against every showcase result's own servers. It
 * drives only the UI contract in `tooling/trial/todo-prompt.md`, so it fits
 * any result that keeps that contract. Each test makes its own titles and
 * never counts todos, because the tests share one api process.
 */
const newTitle = (label: string) => `${label} ${randomUUID().slice(0, 8)}`;

const todoList = (page: Page) => page.getByRole('list', { name: 'Todos' });

const todoItem = (page: Page, title: string) =>
  todoList(page)
    .getByRole('listitem')
    .filter({ has: page.getByRole('checkbox', { name: title, exact: true }) });

/**
 * Clicks and waits for the tRPC mutation the click sends, so a reload never
 * overtakes it, even when the page updates optimistically first.
 */
async function clickAndSave(page: Page, target: Locator) {
  const saved = page.waitForResponse(
    (response) =>
      new URL(response.url()).pathname.startsWith('/trpc') &&
      response.request().method() === 'POST',
  );
  await target.click();
  await saved;
}

async function addTodo(page: Page, title: string) {
  await page.getByRole('textbox', { name: 'Title' }).fill(title);
  await clickAndSave(page, page.getByRole('button', { name: 'Add', exact: true }));
  await expect(todoItem(page, title)).toBeVisible();
}

test.beforeEach(async ({ page }) => {
  await page.goto('/');
});

test.describe('Todo acceptance', () => {
  test('shows the Todos heading, the Title field and the Add button', async ({ page }) => {
    await expect(page.getByRole('heading', { level: 1, name: 'Todos' })).toBeVisible();
    await expect(page.getByRole('textbox', { name: 'Title' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Add', exact: true })).toBeVisible();
  });

  test('creates a todo that appears unchecked in the Todos list', async ({ page }) => {
    const title = newTitle('Buy milk');

    await addTodo(page, title);

    await expect(todoList(page)).toBeVisible();
    await expect(page.getByRole('checkbox', { name: title, exact: true })).not.toBeChecked();
  });

  for (const blank of ['', '   ']) {
    test(`adds nothing and shows an alert for the title ${JSON.stringify(blank)}`, async ({
      page,
    }) => {
      const loaded = newTitle('Loaded marker');
      await addTodo(page, loaded);

      await page.getByRole('textbox', { name: 'Title' }).fill(blank);
      await page.getByRole('button', { name: 'Add', exact: true }).click();

      await expect(page.getByRole('alert').first()).toBeVisible();
      await page.reload();
      await expect(todoItem(page, loaded)).toBeVisible();
      await expect(todoList(page).getByRole('checkbox', { name: /^\s*$/ })).toHaveCount(0);
    });
  }

  test('toggles a todo complete and back, and keeps each state across a reload', async ({
    page,
  }) => {
    const title = newTitle('Walk the dog');
    await addTodo(page, title);
    const checkbox = page.getByRole('checkbox', { name: title, exact: true });

    await clickAndSave(page, checkbox);
    await expect(checkbox).toBeChecked();
    await page.reload();
    await expect(checkbox).toBeChecked();

    await clickAndSave(page, checkbox);
    await expect(checkbox).not.toBeChecked();
    await page.reload();
    await expect(checkbox).not.toBeChecked();
  });

  test('deletes a todo, and it stays gone after a reload', async ({ page }) => {
    const kept = newTitle('Loaded marker');
    const title = newTitle('Water the plants');
    await addTodo(page, kept);
    await addTodo(page, title);

    await clickAndSave(page, page.getByRole('button', { name: `Delete ${title}`, exact: true }));

    await expect(todoItem(page, title)).toHaveCount(0);
    await page.reload();
    await expect(todoItem(page, kept)).toBeVisible();
    await expect(todoItem(page, title)).toHaveCount(0);
  });

  test('has no detectable WCAG 2.1 A or AA violation with a todo listed', async ({ page }) => {
    await addTodo(page, newTitle('Read a book'));

    const scan = await new AxeBuilder({ page })
      .withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa'])
      .analyze();

    expect(scan.violations).toEqual([]);
  });
});
import { defineConfig, devices, type PlaywrightTestConfig } from '@playwright/test';
import { listResults } from './tooling/results.mjs';

/**
 * Playwright is the browser harness for the behaviour map. Each result
 * (`apps/`, then every `showcase/<id>/`) gets one Chromium project that runs
 * every spec in `<result>/web/e2e/`, and two servers: its api on Node and its
 * web app on Vite, which proxies `/trpc` to that api. Each showcase result also
 * gets `<id>-acceptance`, which runs the fixed Todo acceptance spec in
 * `tooling/trial/acceptance/` against the same servers (ADR 0034).
 *
 * The reference's web server runs the production build (`vite build` then
 * `vite preview`, which serves `dist/` and proxies `/trpc` the same way the dev
 * server does) rather than the dev server when `E2E_BUILD` is set to anything
 * other than `0`/`false`, and by default under `CI`. This proves the shipping
 * bundle — bundling, env, base paths and the preview `/trpc` proxy — end to
 * end on every CI run. Local runs
 * default to the fast dev server; set `E2E_BUILD=1` to rehearse the build
 * locally, or `E2E_BUILD=0` to force the dev server in CI. The showcase results
 * stay on the dev server: they are frozen trial evidence (ADR 0034), not the
 * shipping product. `E2E_BASE_URL` still points the reference at a preview you
 * manage yourself (it wins over `E2E_BUILD`), with the api on :3001 that
 * Playwright starts.
 */
const externalBaseUrl = process.env.E2E_BASE_URL;
const reuseExistingServer = !process.env.CI;
const productionBuild =
  process.env.E2E_BUILD === undefined
    ? Boolean(process.env.CI)
    : process.env.E2E_BUILD !== '0' && process.env.E2E_BUILD !== 'false';
const results = listResults(import.meta.dirname);

type WebServer = Extract<PlaywrightTestConfig['webServer'], readonly unknown[]>[number];

const webUrl = (port: number) => `http://127.0.0.1:${port}`;
const usesExternalServer = (id: string) => id === 'reference' && Boolean(externalBaseUrl);
const usesProductionBuild = (id: string) =>
  id === 'reference' && productionBuild && !externalBaseUrl;

export default defineConfig({
  fullyParallel: true,
  forbidOnly: Boolean(process.env.CI),
  retries: process.env.CI ? 2 : 0,
  reporter: process.env.CI ? [['html', { open: 'never' }], ['github']] : 'list',
  use: { trace: 'on-first-retry' },
  projects: [
    ...results.map(({ id, web, ports }) => ({
      name: id,
      testDir: `./${web}/e2e`,
      use: {
        ...devices['Desktop Chrome'],
        baseURL: usesExternalServer(id) ? externalBaseUrl : webUrl(ports.web),
      },
    })),
    ...results
      .filter(({ id }) => id !== 'reference')
      .map(({ id, ports }) => ({
        name: `${id}-acceptance`,
        testDir: './tooling/trial/acceptance',
        use: { ...devices['Desktop Chrome'], baseURL: webUrl(ports.web) },
      })),
  ],
  webServer: results.flatMap(({ id, web, api, ports }): WebServer[] => {
    const apiServer: WebServer = {
      command: `node ${api}/src/server.ts`,
      env: { PORT: String(ports.api) },
      port: ports.api,
      reuseExistingServer,
      timeout: 60_000,
    };
    if (usesExternalServer(id)) {
      return [apiServer];
    }
    // The built web server never reuses an existing server, so a busy port
    // fails explicitly in managed production mode rather than silently serving
    // a stray dev server and skipping the build; the dev server keeps
    // `reuseExistingServer` (api and showcase are unchanged).
    const webServer: WebServer = usesProductionBuild(id)
      ? {
          command: `pnpm build && pnpm exec vite preview --host 127.0.0.1 --port ${ports.web} --strictPort`,
          cwd: web,
          env: { API_ORIGIN: webUrl(ports.api) },
          url: webUrl(ports.web),
          reuseExistingServer: false,
          timeout: 180_000,
        }
      : {
          command: `pnpm exec vite --host 127.0.0.1 --port ${ports.web} --strictPort`,
          cwd: web,
          env: { API_ORIGIN: webUrl(ports.api) },
          url: webUrl(ports.web),
          reuseExistingServer,
          timeout: 120_000,
        };
    return [apiServer, webServer];
  }),
});
