// TEMPLATE — copy to <result>/web/src/routes/<route-name>/__Name__.tsx (for example
// apps/web/src/routes/<route-name>/) and replace the __PLACEHOLDERS__.
// Model: apps/web/src/routes/greeting/GreetingForm.tsx and GreetingPage.tsx.
//
// One component per file, named like the file. A component only renders: it
// takes state from its use* hook (server state through useTrpc(), form state
// through use__Name__Form) and builds controls from @repo/ui. Functions it
// defines start with `handle`; callback props start with `on`.
// See .agents/project/ARCHITECTURE.md.

import { Button } from '@repo/ui';
import { use__Name__ } from './use__Name__';

export interface __Name__Props {
