import { existsSync } from 'node:fs';
import type { Config } from 'jest';

/**
 * Three projects: `web` (jsdom) for every web package and the ui kit, `api`
 * (node) for every api package, and `tooling` for the gate scripts. Each result
 * in `apps/` or `showcase/<id>/` joins by path, with no per-result entry. The
 * transform is @swc/jest (fast, no Babel). Coverage is gated so a feature cannot
 * ship under-tested — see `.agents/project/DEFINITION_OF_DONE.md`.
 */
const existingRoots = (...folders: string[]) =>
  folders.filter((folder) => existsSync(folder)).map((folder) => `<rootDir>/${folder}`);

const shared = {
  setupFilesAfterEnv: ['<rootDir>/jest.setup.ts'],
  moduleNameMapper: {
    '\\.(css|less|scss|sass)$': '<rootDir>/jest.style-stub.cjs',
  },
  transform: {
    // Effect 4 ships ES modules only and reads `import.meta?.env`, which has no
    // CommonJS form; under Jest there is no Vite env, so it reads as undefined.
    '/node_modules/(\\.pnpm/)?effect[@/].+\\.js$': [
      '@swc/jest',
      { jsc: { transform: { optimizer: { globals: { vars: { 'import.meta': 'undefined' } } } } } },
    ],
    // Also transform .mjs so scripts/*.mjs (e.g. validate-pr-body.mjs) can be
    // imported directly by their co-located tests.
    '^.+\\.(t|j)sx?$|^.+\\.mjs$': [
      '@swc/jest',
      {
        jsc: {
          parser: { syntax: 'typescript', tsx: true },
          transform: { react: { runtime: 'automatic' } },
        },
      },
    ],
  },
  transformIgnorePatterns: ['/node_modules/(?!(\\.pnpm/)?effect[@/])'],
} satisfies Config;

const config: Config = {
  // Clears the hook's and CI's variables before any worker starts (ADR 0042).
  globalSetup: '<rootDir>/scripts/jest-global-setup.mjs',
  projects: [
    {
      ...shared,
      displayName: 'web',
      testEnvironment: 'jsdom',
      roots: existingRoots('apps', 'showcase', 'packages'),
      testMatch: [
        '<rootDir>/{apps,showcase/*}/web/src/**/*.test.{ts,tsx}',
        '<rootDir>/packages/*/src/**/*.test.{ts,tsx}',
      ],
    },
    {
      ...shared,
      displayName: 'api',
      testEnvironment: 'node',
      roots: existingRoots('apps', 'showcase'),
      testMatch: ['<rootDir>/{apps,showcase/*}/api/src/**/*.test.{ts,tsx}'],
    },
    {
      ...shared,
      displayName: 'tooling',
      testEnvironment: 'jsdom',
      roots: existingRoots('scripts', 'tooling'),
      testMatch: ['<rootDir>/scripts/**/*.test.{ts,tsx}', '<rootDir>/tooling/**/*.test.{ts,tsx}'],
    },
  ],
  collectCoverageFrom: [
    '{apps,showcase/*}/*/src/**/*.{ts,tsx}',
    'packages/*/src/**/*.{ts,tsx}',
    '!**/*.d.ts',
    // Each project skips its own test files; this keeps one project from
    // counting another's tests as untested sources.
    '!**/*.test.{ts,tsx}',
    // Excluded by design: index.ts files are pure re-export barriers; main.tsx,
    // App.tsx and the api's server.ts are composition roots, exercised by the
    // E2E behaviour map (each result's e2e/ folder) rather than the unit suite.
    // Feature logic is NOT excluded. scripts/jest-scope.test.ts holds this list
    // to that set.
    '!{apps,showcase/*,packages}/**/src/**/index.ts',
    '!{apps,showcase/*}/web/src/main.tsx',
    '!{apps,showcase/*}/web/src/App.tsx',
    '!{apps,showcase/*}/api/src/server.ts',
  ],
  // Jest's defaults plus json-summary, which tooling/coverage-by-result.mjs
  // reads to hold each result to the same threshold on its own.
  coverageReporters: ['clover', 'json', 'lcov', 'text', 'json-summary'],
  coverageThreshold: {
    global: { branches: 80, functions: 80, lines: 80, statements: 80 },
  },
};

export default config;
{
  // The browser program: every web package and the ui kit. It has the DOM and
  // no Node types. It reaches the api only through the type-only `@<scope>/api`
  // contract, and the reference makes it read the declarations the api program
  // writes to `.cache/types`, so api source, Node imports included, is checked
  // by the api program alone. `pnpm typecheck` builds them with `tsc -b`.
  // The root configs and e2e specs run on Node: tsconfig.node.json.
  "extends": "./tsconfig.base.json",
  "compilerOptions": {
    "useDefineForClassFields": true,
    "lib": ["ES2022", "DOM", "DOM.Iterable"],
    "module": "ESNext",
    "moduleResolution": "Bundler",
    "jsx": "react-jsx",
    "allowImportingTsExtensions": true,
    "tsBuildInfoFile": ".cache/types/web.tsbuildinfo",

    "types": ["jest", "@testing-library/jest-dom"]
  },
  "include": ["apps/web/src", "showcase/*/web/src", "packages/ui/src"],
  "references": [{ "path": "./tsconfig.api.json" }],
  "ts-node": {
    "transpileOnly": true,
    "compilerOptions": {
      "module": "CommonJS",
      "moduleResolution": "node",
      "verbatimModuleSyntax": false
    }
  }
}
{
  // The Node program: every api package. Node runs its source with native type
  // stripping, so it sees no DOM, imports relative files with their `.ts`
  // extension, and uses only syntax Node can erase. It is composite so the
  // browser program reads its declarations from `.cache/types`.
  "extends": "./tsconfig.base.json",
  "compilerOptions": {
    "lib": ["ES2022"],
    "module": "NodeNext",
    "moduleResolution": "NodeNext",
    "allowImportingTsExtensions": true,
    "erasableSyntaxOnly": true,
    "types": ["node", "jest"],
    "composite": true,
    "noEmit": false,
    "emitDeclarationOnly": true,
    "rootDir": ".",
    "outDir": ".cache/types",
    "tsBuildInfoFile": ".cache/types/api.tsbuildinfo"
  },
  "include": ["apps/api/src", "showcase/*/api/src"]
}
{
  // The domain program: every api domain module, with no Node types and no
  // DOM, so `process`, `require`, `Buffer` and Node module imports fail to
/**
 * The one place that discovers results. A result is a pair of workspace
 * packages, `<root>/web` and `<root>/api`: the reference in `apps/`, and each
 * independently generated result in `showcase/<id>/`. Gates that run per result
 * (Playwright today) read this list, so a new result needs no config entry.
 */

import { existsSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const REFERENCE_PORTS = { web: 5173, api: 3001 };
const PORT_STEP = 10;

const isResultRoot = (repositoryRoot, root) =>
  existsSync(join(repositoryRoot, root, 'web/package.json')) &&
  existsSync(join(repositoryRoot, root, 'api/package.json'));

/**
 * The reference first, then every `showcase/<id>` with both `web/package.json`
 * and `api/package.json`, sorted by id. Ports step by 10 per result.
 *
 * @param {string} repositoryRoot
 * @returns {readonly import('./results.d.mts').Result[]}
 */
export function listResults(repositoryRoot) {
  const showcase = join(repositoryRoot, 'showcase');
  const ids = existsSync(showcase)
    ? readdirSync(showcase, { withFileTypes: true })
        .filter(
          (entry) => entry.isDirectory() && isResultRoot(repositoryRoot, `showcase/${entry.name}`),
        )
        .map((entry) => entry.name)
        .sort()
    : [];
  const roots = [
    { id: 'reference', root: 'apps', scope: 'repo' },
    ...ids.map((id) => ({ id, root: `showcase/${id}`, scope: id })),
  ];
  return roots.map(({ id, root, scope }, index) => ({
    id,
    root,
    scope,
    web: `${root}/web`,
    api: `${root}/api`,
    ports: {
      web: REFERENCE_PORTS.web + index * PORT_STEP,
      api: REFERENCE_PORTS.api + index * PORT_STEP,
    },
  }));
}

