    todos: list.data ?? [],
    loadFailed: list.isError,
    saveFailed: add.isError || toggle.isError || remove.isError,
    addTodo: (title: Todo['title']) => add.mutate({ title }),
    toggleTodo: (id: Todo['id']) => toggle.mutate({ id }),
    deleteTodo: (id: Todo['id']) => remove.mutate({ id }),
